package co.kr.badara.dolswevoice;
import org.json.*;import java.util.*;
public class CoreTests {
 static int checks=0;static void ok(boolean b){checks++;if(!b)throw new AssertionError("Check "+checks);}interface Task{void run()throws Exception;}static void fails(Task t)throws Exception{boolean failed=false;try{t.run();}catch(IllegalArgumentException|java.io.IOException e){failed=true;}ok(failed);}
 static class Fixture implements HaClient.Transport {Set<String> ids=new HashSet<>(Arrays.asList("light.living"));int posts=0,templates=0;String lastPath="";JSONObject lastData;boolean fail=false,group=false;public String request(String method,String path,JSONObject data)throws Exception{if(path.equals("/api/template")){templates++;if(fail)throw new java.io.IOException("offline");return new JSONArray(ids).toString();}if(path.equals("/api/states"))return "[{\"entity_id\":\"light.living\",\"state\":\"off\",\"attributes\":{\"friendly_name\":\"HA 원래 이름\"}},{\"entity_id\":\"switch.hidden\",\"state\":\"on\"}]";if(path.startsWith("/api/states/")&&group)return "{\"entity_id\":\"light.living\",\"state\":\"on\",\"attributes\":{\"entity_id\":[\"light.hidden\"]}}";if(path.startsWith("/api/states/"))return "{\"entity_id\":\"light.living\",\"state\":\"off\",\"attributes\":{}}";if(path.startsWith("/api/services/")){posts++;lastPath=path;lastData=data;return "[]";}throw new java.io.IOException("unexpected path "+path);}}
 public static void main(String[] args)throws Exception{
  List<CommandRouter.Target> t=Arrays.asList(new CommandRouter.Target("light.living","거실 불"),new CommandRouter.Target("fan.bed","안방 선풍기"),new CommandRouter.Target("climate.air","에어컨"));
  ok(CommandRouter.wake("돌쇠야, 거실 불 켜줘.","돌쇠야, 이모님").matched);ok(CommandRouter.wake("이 모 님!","돌쇠야, 이모님").matched);ok(!CommandRouter.wake("오늘은 이모님 이야기", "이모님").matched);ok(!CommandRouter.wake("돌쇠가","돌쇠야").matched);ok(CommandRouter.wake("자비스 거실 불 켜줘","자비스").matched);
  ok(CommandRouter.wake("돌쓰야 거실 불 켜줘","돌쇠야").matched);ok(!CommandRouter.wake("돌쓰야 거실 불 켜줘","돌쇠야",false).matched);ok(!CommandRouter.wake("놀쇠야 거실 불 켜줘","돌쇠야").matched);ok(!CommandRouter.wake("이모가 왔어요","이모님").matched);
  ok(CommandRouter.plan("거실 불을 켜줘",t).service.equals("turn_on"));ok(CommandRouter.plan("거실 불 꺼주세요",t).service.equals("turn_off"));ok(CommandRouter.plan("안방 선풍기 30퍼센트로 맞춰줘",t).data.get("percentage").equals(30));ok(CommandRouter.plan("거실 불 밝기 50%로 해줘",t).data.get("brightness_pct").equals(50));ok(CommandRouter.plan("에어컨 온도 25도로 맞춰줘",t).data.get("temperature").equals(25));ok(CommandRouter.plan("거실 불 상태 알려줘",t).query());
  fails(()->CommandRouter.plan("거실 불 켜지마",t));fails(()->CommandRouter.plan("거실 불 켜줘 안방 선풍기 꺼줘",t));fails(()->CommandRouter.plan("모든 장치 꺼줘",t));fails(()->CommandRouter.plan("알 수 없는 전등 켜줘",t));fails(()->CommandRouter.plan("거실 불 200퍼센트로 해줘",t));fails(()->CommandRouter.plan("에어컨 99도로 맞춰줘",t));fails(()->CommandRouter.plan("거실 불 켜줘 꺼줘",t));
  ok(!CommandRouter.validateAliases(Arrays.asList(new CommandRouter.Target("light.a","거실 불"),new CommandRouter.Target("light.b","거실불"))).isEmpty());
  Fixture f=new Fixture();HaClient client=new HaClient(f);ok(client.list("음성제어").size()==1);CommandRouter.Plan p=CommandRouter.plan("거실 불 켜줘",t);client.execute("음성제어",p,true);ok(f.posts==0);client.execute("음성제어",p,false);ok(f.posts==1&&f.lastPath.equals("/api/services/light/turn_on"));ok(f.lastData.getString("entity_id").equals("light.living"));f.group=true;fails(()->client.execute("음성제어",p,false));ok(f.posts==1);f.group=false;f.ids.clear();fails(()->client.execute("음성제어",p,false));ok(f.posts==1);ok(client.list("없는라벨").isEmpty());f.fail=true;fails(()->client.execute("음성제어",p,false));ok(f.posts==1);fails(()->client.list(""));fails(()->new HaClient("http://example.com","secret").list("label"));
  System.out.println(checks+" checks passed: wake phrases, alias routing, cancellation, label gating, dry-run, HTTPS.");
 }
}
